                                        <button 
                                            type="submit"
                                            disabled={isLoading || password.length < 4}
                                            className="w-full bg-gold-500 hover:bg-gold-400 disabled:opacity-50 text-mystic-900 font-bold py-3 rounded-xl transition-colors flex items-center justify-center"
