        </div>

        <div className="flex-1 overflow-y-auto pb-20 scrollbar-hide">
            {activeTab === 'daily' && renderDaily()}
            {activeTab === 'weekly' && renderFullForecast('weekly')}
            {activeTab === 'monthly' && renderFullForecast('monthly')}
        </div>
    </div>
  );
};

