      setMessages(prev => [...prev, { 
        id: generateId(), 
        text: responseText, 
        sender: Sender.AI, 
        timestamp: new Date(), 
        isLocked: shouldLock, 
        metadata: shouldLock ? { status: 'waiting_for_sql' } : undefined, // Set Waiting Status for non-premium
