  const handleSeekerLogin = async (contact: string) => {
      setHasStarted(true); 
      setIsGlobalLoading(true);
      setLoadingText("Retrieving destiny...");
      try {
          const { profile, chatHistory } = await fetchUserProfile([contact.trim()]);
