Here is the full SQL command to set up your Supabase database, including all tables required for the Astro21 app (Profiles, Products, Astrologers, Transactions, Logging, and Caching).

You can copy and paste this directly into the **Supabase SQL Editor** to initialize your database.

```sql
-- 1. Enable UUID extension
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 2. Profiles (Linked to Supabase Auth)
CREATE TABLE IF NOT EXISTS public.profiles (
  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  contact TEXT UNIQUE NOT NULL,
  name TEXT,
  gender TEXT,
  birth_date TEXT,
  birth_time TEXT,
  birth_place TEXT,
  is_premium BOOLEAN DEFAULT FALSE,
  daily_questions_left INTEGER DEFAULT 1,
  subscription_expiry TIMESTAMPTZ,
  chat_history TEXT,
  password TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. Products (Marketplace Items)
CREATE TABLE IF NOT EXISTS public.products (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT,
  price NUMERIC DEFAULT 0,
  description TEXT,
  benefits TEXT,
  image_url TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. Astrologers (Consultants)
CREATE TABLE IF NOT EXISTS public.astrologers (
  id TEXT PRIMARY KEY DEFAULT uuid_generate_v4()::text,
  name TEXT NOT NULL,
  specialty TEXT,
  rating NUMERIC DEFAULT 5.0,
  reviews INTEGER DEFAULT 0,
  price_per_min NUMERIC DEFAULT 10,
  image_url TEXT,
  is_online BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 5. Transactions (Purchases & Subscriptions)
CREATE TABLE IF NOT EXISTS public.transactions (
  id TEXT PRIMARY KEY,
  user_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  user_name TEXT,
  amount NUMERIC DEFAULT 0,
  type TEXT,
  status TEXT,
  details TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 6. Communications Log (Emails/SMS/Calls)
CREATE TABLE IF NOT EXISTS public.communications (
  id TEXT PRIMARY KEY,
  type TEXT,
  recipient TEXT,
  direction TEXT,
  status TEXT,
  details TEXT,
  timestamp TIMESTAMPTZ DEFAULT NOW()
);

-- 7. Usage Logs (Token Tracking)
CREATE TABLE IF NOT EXISTS public.usage_logs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  feature TEXT,
  input_tokens INTEGER DEFAULT 0,
  output_tokens INTEGER DEFAULT 0,
  total_tokens INTEGER DEFAULT 0,
  timestamp TIMESTAMPTZ DEFAULT NOW()
);

-- 8. Natal Cache (To store generated horoscopes)
CREATE TABLE IF NOT EXISTS public.natal_cache (
  id TEXT PRIMARY KEY,
  response TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 9. Enable Row Level Security (RLS)
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.astrologers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.transactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.communications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.usage_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.natal_cache ENABLE ROW LEVEL SECURITY;

-- 10. RLS Policies

-- Profiles: Users can view/update their own profile
CREATE POLICY "Users can view own profile" ON public.profiles FOR SELECT USING (auth.uid() = id);
CREATE POLICY "Users can update own profile" ON public.profiles FOR UPDATE USING (auth.uid() = id);
CREATE POLICY "Users can insert own profile" ON public.profiles FOR INSERT WITH CHECK (auth.uid() = id);

-- Products: Public read access
CREATE POLICY "Public read products" ON public.products FOR SELECT USING (true);
CREATE POLICY "Admin insert products" ON public.products FOR INSERT WITH CHECK (true); -- Ideally restrict to admin
CREATE POLICY "Admin update products" ON public.products FOR UPDATE USING (true);
CREATE POLICY "Admin delete products" ON public.products FOR DELETE USING (true);

-- Astrologers: Public read access
CREATE POLICY "Public read astrologers" ON public.astrologers FOR SELECT USING (true);
CREATE POLICY "Admin manage astrologers" ON public.astrologers FOR ALL USING (true);

-- Transactions: Users can view their own history
CREATE POLICY "Users view own transactions" ON public.transactions FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Users insert own transactions" ON public.transactions FOR INSERT WITH CHECK (auth.uid() = user_id);

-- Communications: Open access for system logging (Simplify for demo)
CREATE POLICY "System log access" ON public.communications FOR ALL USING (true);

-- Usage Logs: Users/System can insert
CREATE POLICY "Insert usage logs" ON public.usage_logs FOR INSERT WITH CHECK (true);

-- Natal Cache: Public read for cached readings
CREATE POLICY "Public read cache" ON public.natal_cache FOR SELECT USING (true);
CREATE POLICY "Public insert cache" ON public.natal_cache FOR INSERT WITH CHECK (true);

