export const fetchUserProfile = async (contact: string | string[]): Promise<{ profile: any | null, chatHistory: Message[] }> => {
  if (!supabase) return { profile: null, chatHistory: [] };
  try {
      let query = supabase.from('profiles').select('*');
      if (Array.isArray(contact)) query = query.in('contact', contact); else query = query.eq('contact', contact);
      const { data, error } = await query.limit(1).maybeSingle();
      if (error || !data) return { profile: null, chatHistory: [] };

      let messages: Message[] = [];
      if (data.chat_history) {
          const decrypted = decryptAndDecompress(data.chat_history);
          if (decrypted) messages = decrypted.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) }));
      }

      // Explicit Mapping from DB (snake_case) to App (CamelCase)
      const mappedProfile = { 
          id: data.id, 
          contact: data.contact, 
          name: data.name, 
          gender: data.gender, 
          birthDate: data.birth_date, // snake_case from DB
          birthTime: data.birth_time, // snake_case from DB
          birthPlace: data.birth_place, // snake_case from DB
          isPremium: data.is_premium, // snake_case from DB
          dailyQuestionsLeft: data.daily_questions_left, // snake_case from DB
          subscriptionExpiry: data.subscription_expiry ? new Date(data.subscription_expiry) : undefined, // snake_case from DB
          password: data.password 
      };

      return {
        profile: mappedProfile,
        chatHistory: messages
      };
  } catch (e) { return { profile: null, chatHistory: [] }; }
};

export const generateUniqueUsername = async (fullName: string): Promise<string> => {
    // Return full name to respect user input. Duplicates are allowed as unique ID is handled by UUID/Contact.
    return fullName.trim();
};

export const saveUserProfile = async (user: UserState, password?: string, messages?: Message[]) => {
  if (!supabase || !user.contact) return;
  try {
      const payload: any = {
        contact: user.contact,
        name: user.name || '',
        gender: user.gender || '',
        birth_date: user.birthDate || '', // Storing as snake_case
        birth_time: user.birthTime || '', // Storing as snake_case
        birth_place: user.birthPlace || '', // Storing as snake_case
        is_premium: !!user.isPremium,
        daily_questions_left: typeof user.dailyQuestionsLeft === 'number' ? user.dailyQuestionsLeft : 0,
        subscription_expiry: user.subscriptionExpiry ? user.subscriptionExpiry.toISOString() : null
      };
      if (password) payload.password = await hashPassword(password);
      if (messages && messages.length > 0) payload.chat_history = compressAndEncrypt(messages);

      // Prefer ID if available (UUID), otherwise fallback to contact
      if (user.id) {
         await supabase.from('profiles').update(payload).eq('id', user.id);
      } else {
         await supabase.from('profiles').upsert(payload, { onConflict: 'contact' });
      }
  } catch (e) { console.error("DB: Exception saving profile", e); }
};

import { GoogleGenAI, Chat, Schema } from "@google/genai";
import { BASE_SYSTEM_INSTRUCTION } from '../constants';
import { logTokenUsage } from './dbService';
import { verifyJWT } from './securityService';

let ai: GoogleGenAI | null = null;
let chatSession: Chat | null = null;
let currentInstruction: string = BASE_SYSTEM_INSTRUCTION;

// Helper to identify user from token or context
const getCurrentUserId = (): string => {
    const token = localStorage.getItem('astro_token');
    if (token) {
        return verifyJWT(token) || 'anonymous';
    }
    return 'anonymous';
};

const trackUsageToDb = (prompt: string, response: string, feature: 'chat' | 'horoscope' = 'chat') => {
    // Estimate tokens: 1 token ~= 4 chars (Rough Estimate)
    // Detailed analysis shows approx 0.25 tokens per char
    const inputTokens = Math.ceil(prompt.length / 4);
    const outputTokens = Math.ceil(response.length / 4);

    // Log directly to Supabase via dbService
    const userId = getCurrentUserId();
    logTokenUsage(userId, feature, inputTokens, outputTokens);
};

const getAI = () => {
  if (!ai) {
    if (!process.env.API_KEY) {
      console.error("API_KEY is missing from environment variables");
      throw new Error("API Key missing");
    }
    ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  }
  return ai;
};

export const initializeChat = async (customInstruction?: string): Promise<Chat> => {
  const client = getAI();

  if (customInstruction) {
    currentInstruction = customInstruction;
  }

  chatSession = client.chats.create({
    model: 'gemini-3-flash-preview',
    config: {
      systemInstruction: currentInstruction,
      temperature: 0.7,
      maxOutputTokens: 8192, // Increased to prevent truncation
    }
  });
  return chatSession;
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const sendMessageToGemini = async (message: string, isPremium: boolean = false): Promise<string> => {
  if (!chatSession) {
    await initializeChat();
  }
  if (!chatSession) {
    throw new Error("Failed to initialize chat session");
  }

  const maxRetries = 3;
  let attempt = 0;

  // We now require full Deep Dive content for all users (to support unlock feature),
  // so we do not strip the request for free users.
  // The system instruction enforces the structure "Gist ... Deep Dive: ..."
  let apiPrompt = message;

  if (isPremium) {
     apiPrompt = `${message} 

     [PREMIUM REQUEST]: Provide a rich, detailed 'Deep Dive' section. Include specific planetary alignments, Dasha implications, and concrete remedies. Be precise and avoid vague spiritual platitudes. Focus on actionable astrological data.`;
  }

  while (attempt < maxRetries) {
    try {
      const result = await chatSession.sendMessage({
        message: apiPrompt
      });
      const responseText = result.text || "The stars are clouded...";

      // Log DB Usage
      trackUsageToDb(apiPrompt, responseText, 'chat');

      return responseText;
    } catch (error: any) {
      const isQuotaError = error?.status === 429 || error?.code === 429 || error?.message?.includes('quota');
      if (isQuotaError) {
        attempt++;
        if (attempt < maxRetries) {
            await delay(Math.pow(2, attempt) * 1000);
            continue;
        }
      }
      return "A cosmic interference disrupted my connection. Please try again.";
    }
  }
  return "Connection failed.";
};

export const generateJsonContent = async (prompt: string, maxTokens: number = 4000, schema?: Schema): Promise<any> => {
    const client = getAI();
    try {
        const response = await client.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                responseMimeType: 'application/json',
                responseSchema: schema,
                maxOutputTokens: maxTokens
            }
        });

        let text = response.text;
        if (!text) return null;

        // Log DB Usage
        trackUsageToDb(prompt, text, 'horoscope');

        if (text.trim().startsWith('```')) {
            text = text.replace(/^```json\s*/, '').replace(/^```\s*/, '').replace(/```$/, '').trim();
        }

        try {
            return JSON.parse(text);
        } catch (parseError) {
            console.warn("JSON Parse failed, attempting standard cleanup", parseError);
            const cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
            try {
                 return JSON.parse(cleanText);
            } catch (e2) {
                 console.error("Final JSON Parse Error. Raw text:", text);
                 return null; 
            }
        }
    } catch (e) {
        console.error("JSON Generation Error:", e);
        return null;
    }
};

