                        {showScrollButton && <button onClick={scrollToBottom} className="fixed bottom-36 right-6 md:right-[calc(50%-20px)] md:left-auto md:translate-x-full z-40 bg-mystic-800 p-3 rounded-full border border-gold-500/30 shadow-lg text-gold-400 hover:bg-mystic-700 transition-all animate-bounce">↓</button>}
                        <div className="fixed bottom-0 left-0 w-full z-40 pointer-events-none">
                            <div className="max-w-5xl mx-auto relative px-4 pb-6 pt-4 bg-gradient-to-t from-mystic-900 via-mystic-900 to-transparent pointer-events-auto">
                                {!isAiThinking && !userState.connectedAstrologerId && (
                                    <div className="flex gap-2 overflow-x-auto scrollbar-hide mb-3 pb-1">{currentSuggestions.map((q, i) => (<button key={i} onClick={() => handleSendMessage(q)} disabled={isAiThinking} className="whitespace-nowrap px-3 py-1.5 bg-mystic-800/80 hover:bg-gold-500/20 border border-mystic-600 rounded-full text-xs text-mystic-200 disabled:opacity-50 transition-colors">✨ {q}</button>))}</div>
                                )}
                                <div className="relative flex items-center bg-mystic-800/80 backdrop-blur-xl border border-mystic-600/30 rounded-full p-2 shadow-2xl gap-2">
                                    <button onMouseDown={startRecording} className={`p-2 transition-all rounded-full ${isRecording ? 'bg-red-500 text-white animate-pulse' : 'text-mystic-400 hover:text-white'}`}><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg></button>
                                    <input type="text" value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()} placeholder={userState.connectedAstrologerId ? "Message Guru..." : t.typeMessage} disabled={isAiThinking || (userState.dailyQuestionsLeft <= 0 && !userState.connectedAstrologerId && !userState.isAdminImpersonating)} className="flex-1 bg-transparent border-none focus:ring-0 text-white placeholder-mystic-400 px-2 py-2 font-sans text-lg outline-none disabled:opacity-50" />
                                    <button onClick={() => handleSendMessage()} disabled={!input.trim() || isAiThinking} className="w-12 h-12 rounded-full bg-gradient-to-br from-violet-600 to-indigo-600 flex items-center justify-center text-white hover:shadow-lg disabled:opacity-50 transition-all transform hover:scale-105"><svg className="w-6 h-6 ml-0.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg></button>
                                </div>
                            </div>
                        </div>
                    </div>
                ) : view === AppView.MARKETPLACE ? (
                    <div className="flex-1 overflow-y-auto scrollbar-hide animate-in fade-in slide-in-from-right-4 duration-300 p-4 md:p-0">
                        <div className="text-center mb-8 mt-4"><h2 className="text-3xl font-serif text-white mb-2">{t.gurus}</h2><p className="text-mystic-300">Consult verified astrologers.</p></div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pb-10">{astrologers.map(astro => (<AstroCard key={astro.id} astrologer={astro} onConnect={connectToAstrologer} connectedAstrologerId={userState.connectedAstrologerId}/>))}</div>
                    </div>
                ) : ( <Shop products={products} onBuy={initiateProductPurchase} /> )}
            </>
        )}
      </main>

      {showPaymentConfirmation && pendingPayment && <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/90"><div className="bg-mystic-800 p-8 rounded-3xl text-center"><h3 className="text-xl font-serif text-white mb-2">Confirm Payment</h3><p className="text-mystic-300 mb-6">₹{pendingPayment.amount}</p><div className="flex gap-3"><button onClick={()=>setShowPaymentConfirmation(false)} className="flex-1 bg-white/5 py-3 rounded-xl text-white">Cancel</button><button onClick={proceedToRazorpay} className="flex-1 bg-gold-500 py-3 rounded-xl text-black font-bold">Pay Now</button></div></div></div>}
      {showChartModal && <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/90"><div className="bg-mystic-900 border border-gold-500/50 p-6 rounded-3xl w-full max-w-lg relative"><button onClick={()=>setShowChartModal(false)} className="absolute top-4 right-4 text-white">✕</button><NatalChart name={userState.name} date={userState.birthDate||''} time={userState.birthTime||''} place={userState.birthPlace||''} allowDownload={true} isPremium={userState.isPremium} onUnlock={()=>{setShowChartModal(false);setShowPremiumModal(true)}}/></div></div>}
      {showProfileModal && <ProfileModal user={userState} onSave={(u)=>setUserState(p=>({...p,...u}))} onClose={()=>setShowProfileModal(false)}/>}
      {showTipModal && <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60"><div className="bg-mystic-800 p-6 rounded-2xl w-full max-w-xs text-center"><h3 className="text-gold-400 mb-4">Support Guru</h3><input type="number" value={tipAmount} onChange={e=>setTipAmount(e.target.value)} className="w-full bg-mystic-900 p-2 mb-4 text-white text-center"/><button onClick={()=>{const a=Number(tipAmount); if(a>0) handleGuruDakshina(a)}} className="w-full bg-gold-500 text-black font-bold py-2 rounded">Send</button><button onClick={()=>setShowTipModal(false)} className="mt-3 text-xs text-gray-400">Cancel</button></div></div>}
      {showAddressModal && <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/90"><div className="bg-mystic-800 p-6 rounded-3xl w-full max-w-md"><h4 className="font-bold text-white mb-4">Shipping</h4><input value={shippingDetails.address} onChange={e=>setShippingDetails({...shippingDetails, address:e.target.value})} placeholder="Address" className="w-full bg-mystic-900 p-3 mb-2 text-white rounded"/><input value={shippingDetails.city} onChange={e=>setShippingDetails({...shippingDetails, city:e.target.value})} placeholder="City" className="w-full bg-mystic-900 p-3 mb-2 text-white rounded"/><button onClick={confirmPurchaseWithAddress} className="w-full bg-gold-500 text-black font-bold py-3 rounded mt-4">Proceed</button><button onClick={()=>setShowAddressModal(false)} className="w-full mt-2 text-gray-400">Cancel</button></div></div>}
      {showRatingModal && ratingTarget && <RatingModal guruName={ratingTarget.name} guruImage={ratingTarget.imageUrl} onSubmit={()=>setShowRatingModal(false)} onSkip={()=>setShowRatingModal(false)}/>}
      {showPremiumModal && <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80"><div className="bg-mystic-800 p-8 rounded-3xl text-center"><button onClick={()=>setShowPremiumModal(false)} className="absolute top-4 right-4 text-white">✕</button><h3 className="text-2xl font-serif text-white mb-2">Unlock</h3><p className="text-gold-400 mb-4">{premiumModalReason}</p><button onClick={handleSubscriptionSuccess} className="w-full bg-gold-500 text-black font-bold py-4 rounded-xl mb-2">Subscribe ₹299</button><button onClick={()=>initiatePayment(99, "One Q", ()=>{setUserState(p=>({...p, dailyQuestionsLeft:p.dailyQuestionsLeft+1})); setShowPremiumModal(false);})} className="w-full bg-white/10 text-white font-bold py-3 rounded-xl">Ask 1 Q (₹99)</button></div></div>}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Product, Transaction, SubscriptionTier, Astrologer, CommunicationLog, Message, Sender } from '../../types';
import { DEFAULT_SUBSCRIPTION_TIERS, AVAILABLE_FEATURES } from '../../constants';
import { saveAstrologer, deleteAstrologer, updateProfile, createProduct, deleteProductFromDb, fetchUsageStats } from '../../services/dbService';
import { decryptAndDecompress } from '../../services/securityService';

interface AdminDashboardProps {
  products: Product[];
  transactions: Transaction[];
  astrologers: Astrologer[];
  users: any[];
  commLogs: CommunicationLog[];
  onUpdateProducts: (products: Product[]) => void;
  onLogout: () => void;
  onImpersonate: (user: any) => void;
  onRefresh?: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
    products, 
    transactions, 
    astrologers, 
    users, 
    commLogs, 
    onUpdateProducts, 
    onLogout, 
    onImpersonate,
    onRefresh
}) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'shop' | 'users' | 'gurus' | 'finance' | 'communications' | 'subscriptions'>('overview');
  const [searchTerm, setSearchTerm] = useState('');

  const [filterStatus, setFilterStatus] = useState('all');
  const [tiers, setTiers] = useState<SubscriptionTier[]>(DEFAULT_SUBSCRIPTION_TIERS);

  // Real-time API Usage Stats from DB
  const [usageStats, setUsageStats] = useState({ totalRequests: 0, estimatedTokens: 0 });

  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [isProductModalOpen, setIsProductModalOpen] = useState(false);

  const [editingAstro, setEditingAstro] = useState<Partial<Astrologer> | null>(null);
  const [isAstroModalOpen, setIsAstroModalOpen] = useState(false);

  const [editingUser, setEditingUser] = useState<any | null>(null);
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);

  const [editingTier, setEditingTier] = useState<SubscriptionTier | null>(null);
  const [isTierModalOpen, setIsTierModalOpen] = useState(false);

  const [viewingChatUser, setViewingChatUser] = useState<any | null>(null);
  const [userChatHistory, setUserChatHistory] = useState<Message[]>([]);
  const [isChatReviewOpen, setIsChatReviewOpen] = useState(false);

  useEffect(() => {
      // Always fetch overview stats on load
      fetchUsageStats().then(setUsageStats);
  }, [activeTab]);

  const handleEditProduct = (product: Product) => { setEditingProduct(product); setIsProductModalOpen(true); };
  const handleCreateProduct = () => { setEditingProduct({ id: `p${Date.now()}`, name: '', category: 'pooja', price: 0, description: '', benefits: '', imageUrl: 'https://images.unsplash.com/photo-1615655406736-b37c4fabf923?auto=format&fit=crop&w=500&q=80' }); setIsProductModalOpen(true); };
  const saveProduct = async () => { if (!editingProduct) return; const saved = await createProduct(editingProduct); if (saved) { const existingIdx = products.findIndex(p => p.id === editingProduct.id || p.id === saved.id); let updatedProducts = [...products]; if (existingIdx >= 0) updatedProducts[existingIdx] = saved; else updatedProducts.push(saved); onUpdateProducts(updatedProducts); setIsProductModalOpen(false); setEditingProduct(null); } };
  const deleteProduct = async (id: string) => { if (window.confirm("Delete?")) { const success = await deleteProductFromDb(id); if (success) onUpdateProducts(products.filter(p => p.id !== id)); } };

  const handleEditAstro = (astro: Astrologer) => { setEditingAstro(astro); setIsAstroModalOpen(true); };
  const handleCreateAstro = () => { setEditingAstro({ name: '', specialty: 'Vedic', rating: 5.0, reviews: 0, pricePerMin: 20, imageUrl: 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=200&q=80', isOnline: false }); setIsAstroModalOpen(true); };
  const saveAstro = async () => { if (!editingAstro) return; await saveAstrologer(editingAstro); setIsAstroModalOpen(false); setEditingAstro(null); };
  const removeAstro = async (id: string) => { if(window.confirm("Delete?")) await deleteAstrologer(id); };

  const handleEditUser = (user: any) => { setEditingUser(user); setIsUserModalOpen(true); };
  const saveUserUpdates = async () => { if (!editingUser) return; await updateProfile(editingUser.id, { is_premium: editingUser.is_premium, daily_questions_left: editingUser.daily_questions_left, name: editingUser.name }); setIsUserModalOpen(false); };
  const handleViewUserChat = (user: any) => { setViewingChatUser(user); if (user.chat_history) { const decrypted = decryptAndDecompress(user.chat_history); setUserChatHistory(decrypted || []); } else { setUserChatHistory([]); } setIsChatReviewOpen(true); };

  const handleEditTier = (tier: SubscriptionTier) => { setEditingTier({ ...tier }); setIsTierModalOpen(true); };
  const toggleFeature = (featureId: string) => { if (!editingTier) return; const hasFeature = editingTier.featureFlags.includes(featureId); let newFlags = hasFeature ? editingTier.featureFlags.filter(f => f !== featureId) : [...editingTier.featureFlags, featureId]; setEditingTier({ ...editingTier, featureFlags: newFlags }); };
  const saveTierUpdates = () => { if (!editingTier) return; setTiers(prev => prev.map(t => t.id === editingTier.id ? editingTier : t)); setIsTierModalOpen(false); };

  const renderOverview = () => {
      const totalRevenue = transactions.reduce((sum, t) => sum + t.amount, 0);
      return (
          <div className="space-y-6 animate-in fade-in">
              <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                  <div className="bg-gradient-to-br from-mystic-800 to-mystic-900 p-6 rounded-2xl border border-gold-500/30 shadow-lg relative overflow-hidden group">
                      <div className="absolute top-0 right-0 p-4 opacity-10 text-6xl group-hover:scale-110 transition-transform">💰</div>
                      <h3 className="text-gold-400 uppercase tracking-widest text-xs font-bold mb-2">Total Revenue</h3>
                      <p className="text-3xl font-serif text-white font-bold">₹{totalRevenue.toLocaleString()}</p>
                      <div className="w-full bg-mystic-950 h-1 rounded-full mt-4 overflow-hidden"><div className="bg-gold-500 h-full" style={{ width: '100%' }}></div></div>
                  </div>

                  <div className="bg-gradient-to-br from-mystic-800 to-mystic-900 p-6 rounded-2xl border border-white/5 shadow-lg relative overflow-hidden">
                      <div className="absolute top-0 right-0 p-4 opacity-10 text-6xl">👥</div>
                      <h3 className="text-mystic-400 uppercase tracking-widest text-xs font-bold mb-2">Total Seekers</h3>
                      <p className="text-3xl font-serif text-white font-bold">{users.length}</p>
                  </div>

                   <div className="bg-gradient-to-br from-mystic-800 to-mystic-900 p-6 rounded-2xl border border-white/5 shadow-lg relative overflow-hidden">
                      <div className="absolute top-0 right-0 p-4 opacity-10 text-6xl">🧘</div>
                      <h3 className="text-mystic-400 uppercase tracking-widest text-xs font-bold mb-2">Active Gurus</h3>
                      <p className="text-3xl font-serif text-white font-bold">{astrologers.filter(a => a.isOnline).length} / {astrologers.length}</p>
                  </div>

                  <div className="bg-gradient-to-br from-mystic-800 to-mystic-900 p-6 rounded-2xl border border-white/5 shadow-lg relative overflow-hidden">
                      <div className="absolute top-0 right-0 p-4 opacity-10 text-6xl">📦</div>
                      <h3 className="text-mystic-400 uppercase tracking-widest text-xs font-bold mb-2">Products</h3>
                      <p className="text-3xl font-serif text-white font-bold">{products.length}</p>
                  </div>
              </div>

              {/* API Monitor Section */}
              <div className="bg-mystic-900 border border-indigo-500/30 rounded-2xl p-6 shadow-2xl relative overflow-hidden">
                  <div className="absolute top-0 right-0 p-8 opacity-5 text-9xl">📡</div>
                  <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                      <div className="space-y-2">
                          <h3 className="text-indigo-400 font-bold uppercase tracking-widest text-sm flex items-center gap-2">
                              <span>🔮</span> Cosmic Engine Monitor
                          </h3>
                          <p className="text-xs text-mystic-400">Real-time usage tracking from Supabase</p>
                      </div>
                      <div className="flex gap-4">
                         <div className="bg-white/5 p-4 rounded-xl border border-white/5 text-center min-w-[120px]">
                            <p className="text-[10px] text-mystic-400 uppercase mb-1">Total Requests</p>
                            <p className="text-2xl font-bold text-white font-mono">{usageStats.totalRequests}</p>
                         </div>
                         <div className="bg-white/5 p-4 rounded-xl border border-white/5 text-center min-w-[120px]">
                            <p className="text-[10px] text-mystic-400 uppercase mb-1">Est. Tokens</p>
                            <p className="text-2xl font-bold text-indigo-400 font-mono">{usageStats.estimatedTokens.toLocaleString()}</p>
                         </div>
                         <div className="bg-white/5 p-4 rounded-xl border border-white/5 text-center min-w-[120px]">
                            <p className="text-[10px] text-mystic-400 uppercase mb-1">Est. Cost</p>
                            <p className="text-2xl font-bold text-green-400 font-mono">Free Tier</p>
                         </div>
                      </div>
                  </div>
                  <div className="mt-8">
                      <div className="flex justify-between items-end mb-2">
                          <span className="text-[10px] text-mystic-500 font-bold uppercase tracking-widest">Global Traffic Intensity</span>
                          <span className="text-xs font-bold text-indigo-300">Live</span>
                      </div>
                      <div className="w-full bg-mystic-800 h-2 rounded-full overflow-hidden border border-white/5">
                          <div 
                            className="bg-gradient-to-r from-green-500 via-indigo-500 to-red-500 h-full transition-all duration-1000" 
                            style={{ width: `${Math.min((usageStats.totalRequests / 1000) * 100, 100)}%` }}
                          ></div>
                      </div>
                  </div>
              </div>
          </div>
      );
  };

  const renderSeekers = () => {
      const filtered = users.filter(u => {
          const matchName = u.name?.toLowerCase().includes(searchTerm.toLowerCase()) || u.contact?.includes(searchTerm);
          const matchStatus = filterStatus === 'all' ? true : filterStatus === 'premium' ? u.is_premium : !u.is_premium;
          return matchName && matchStatus;
      });

      return (
      <div className="animate-in fade-in">
          <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
            <h3 className="text-xl font-bold text-white">Registered Seekers</h3>
            <div className="flex gap-2 w-full md:w-auto">
                 <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)} className="bg-mystic-900 border border-mystic-700 rounded-lg px-3 py-2 text-sm text-white outline-none">
                     <option value="all">All Users</option>
                     <option value="premium">Premium Only</option>
                     <option value="free">Free Only</option>
                 </select>
                 <input type="text" placeholder="Search users..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="bg-mystic-900 border border-mystic-700 rounded-lg px-4 py-2 text-sm text-white w-full md:w-64 outline-none" />
            </div>
          </div>

          <div className="bg-mystic-900/50 border border-white/10 rounded-xl overflow-hidden shadow-xl">
             <div className="overflow-x-auto">
                 <table className="w-full text-sm text-left">
                    <thead className="bg-mystic-800 text-mystic-400 uppercase text-xs font-bold border-b border-white/5">
                        <tr>
                            <th className="px-6 py-4">User</th>
                            <th className="px-6 py-4">Status</th>
                            <th className="px-6 py-4">Daily Limit</th>
                            <th className="px-6 py-4">Created</th>
                            <th className="px-6 py-4 text-center">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-white/5">
                        {filtered.map(user => (
                            <tr key={user.id} className="hover:bg-white/5 transition-colors group">
                                <td className="px-6 py-4">
                                    <div className="flex items-center gap-3">
                                         <div className="w-8 h-8 rounded-full bg-gradient-to-br from-violet-600 to-indigo-900 flex items-center justify-center text-white font-bold text-xs shadow-inner">
                                            {user.name?.charAt(0) || 'U'}
                                         </div>
                                         <div>
                                            <p className="font-bold text-white group-hover:text-gold-400 transition-colors">{user.name}</p>
                                            <p className="text-xs text-mystic-400 font-mono">{user.contact}</p>
                                         </div>
                                    </div>
                                </td>
