                text:txt, 
                sender:Sender.AI, 
                timestamp:new Date(), 
                isLocked: shouldLock, 
                metadata: shouldLock ? { status: 'locked' } : undefined,
                suggestedProducts: suggestedProducts.length > 0 ? suggestedProducts : undefined
            }]);
