          user_name: tx.userName, 
          amount: tx.amount, 
          type: tx.type, 
          details: tx.details, 
          status: tx.status, 
          created_at: new Date().toISOString() 
      }]); 
      if (error) console.error("DB: Transaction save failed", error);
  } catch (e) { console.error("DB: Exception saving transaction", e); }
};

