import { GoogleGenAI, Chat, Schema } from "@google/genai";
import { BASE_SYSTEM_INSTRUCTION } from '../constants';
import { logTokenUsage } from './dbService';
import { verifyJWT } from './securityService';

let ai: GoogleGenAI | null = null;
let chatSession: Chat | null = null;
let currentInstruction: string = BASE_SYSTEM_INSTRUCTION;

// Helper to identify user from token or context
const getCurrentUserId = (): string => {
    const token = localStorage.getItem('astro_token');
    if (token) {
        return verifyJWT(token) || 'anonymous';
    }
    return 'anonymous';
};

const trackUsageToDb = (prompt: string, response: string, feature: 'chat' | 'horoscope' = 'chat') => {
    // Estimate tokens: 1 token ~= 4 chars (Rough Estimate)
    const inputTokens = Math.ceil(prompt.length / 4);
    const outputTokens = Math.ceil(response.length / 4);

    // Log directly to Supabase via dbService
    const userId = getCurrentUserId();
    logTokenUsage(userId, feature, inputTokens, outputTokens);
};

const getAI = () => {
  if (!ai) {
    if (!process.env.API_KEY) {
      console.warn("API_KEY missing. Using fallback mode.");
      // Do not throw, return null so we can fallback gracefully
      return null;
    }
    ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  }
  return ai;
};

// FALLBACK GENERATOR (Demo Mode)
const generateFallbackResponse = (query: string): string => {
    const q = query.toLowerCase();
    let gist = "The stars whisper of change and opportunity.";
    let deepDive = "Saturn's transit suggests patience. Focus on inner growth.";

    if (q.includes('love') || q.includes('marriage')) {
        gist = "Venus radiates harmony. Connections deepen this week.";
        deepDive = "Venus in the 7th house indicates strong relationship prospects. If single, new encounters are likely. If committed, resolve disputes now. Wear pink or use Rose Quartz for alignment.";
    } else if (q.includes('money') || q.includes('wealth') || q.includes('job')) {
        gist = "Jupiter blesses your financial sector. Growth is imminent.";
        deepDive = "A Dhan Yoga is forming. Career advancements are favored, but avoid risky speculations. Place a Kuber Yantra in the North of your home for stability.";
    } else if (q.includes('health')) {
        gist = "Vitality is returning, but rest is essential.";
        deepDive = "Sun's aspect requires you to watch your digestion and energy levels. Chant 'Om Suryaya Namaha' at sunrise. Avoid heavy foods after sunset.";
    }

    return `${gist}\n\nDeep Dive:\n${deepDive}\n\n(Demo Mode: API Connection Unavailable)`;
};

export const initializeChat = async (customInstruction?: string): Promise<Chat | null> => {
  const client = getAI();
  if (!client) return null; // Fallback will handle null session

  if (customInstruction) {
    currentInstruction = customInstruction;
  }

  try {
      chatSession = client.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
          systemInstruction: currentInstruction,
          temperature: 0.7,
          maxOutputTokens: 8192, 
        }
      });
      return chatSession;
  } catch (e) {
      console.warn("Failed to create chat session (Keys might be invalid).", e);
      chatSession = null;
      return null;
  }
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const sendMessageToGemini = async (message: string, isPremium: boolean = false): Promise<string> => {
  // If session is null (init failed or key missing), use fallback immediately
  if (!chatSession) {
      // Try initializing one last time
      await initializeChat();
      if (!chatSession) {
          console.warn("No Chat Session. Using Demo Fallback.");
          return generateFallbackResponse(message);
      }
  }

  const maxRetries = 2;
  let attempt = 0;

  let apiPrompt = message;
  if (isPremium) {
     apiPrompt = `${message} 

     [PREMIUM REQUEST]: Provide a rich, detailed 'Deep Dive' section. Include specific planetary alignments, Dasha implications, and concrete remedies. Be precise and avoid vague spiritual platitudes. Focus on actionable astrological data.`;
  }

  while (attempt < maxRetries) {
    try {
      if (!chatSession) throw new Error("Session lost");

      const result = await chatSession.sendMessage({
        message: apiPrompt
      });

      const responseText = result.text;
      if (!responseText) throw new Error("Empty response");

      // Log DB Usage
      trackUsageToDb(apiPrompt, responseText, 'chat');

      return responseText;
    } catch (error: any) {
      console.error("Gemini API Error:", error);

      // CRITICAL: If API Key is invalid or quota exceeded, switch to fallback
      if (
          error.status === 400 || // Bad Request (often invalid key format)
          error.status === 403 || // Forbidden (Key invalid)
          error.message?.includes('API key') ||
          error.message?.includes('fetch failed') // Network issue
      ) {
          console.warn("API Key Invalidated or Network Error. Switching to Demo Mode.");
          return generateFallbackResponse(message);
      }

      const isQuotaError = error?.status === 429 || error?.code === 429 || error?.message?.includes('quota');
      if (isQuotaError) {
        attempt++;
        if (attempt < maxRetries) {
            await delay(Math.pow(2, attempt) * 1000);
            continue;
        }
      }

      // If we exhausted retries or it's another error, fallback
      return generateFallbackResponse(message);
    }
  }
  return generateFallbackResponse(message);
};

export const generateJsonContent = async (prompt: string, maxTokens: number = 4000, schema?: Schema): Promise<any> => {
    const client = getAI();
    if (!client) return null;

    try {
        const response = await client.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                responseMimeType: 'application/json',
                responseSchema: schema,
                maxOutputTokens: maxTokens
            }
        });

        let text = response.text;
        if (!text) return null;

        trackUsageToDb(prompt, text, 'horoscope');

        if (text.trim().startsWith('```')) {
            text = text.replace(/^```json\s*/, '').replace(/^```\s*/, '').replace(/```$/, '').trim();
        }

        try {
            return JSON.parse(text);
        } catch (parseError) {
            const cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
            try { return JSON.parse(cleanText); } catch (e2) { return null; }
        }
    } catch (e) {
        console.error("JSON Generation Error:", e);
        return null;
    }
};

