import { GoogleGenAI, Chat, Schema } from "@google/genai";
import { BASE_SYSTEM_INSTRUCTION } from '../constants';
import { logTokenUsage } from './dbService';
import { verifyJWT } from './securityService';

let ai: GoogleGenAI | null = null;
let chatSession: Chat | null = null;
let currentInstruction: string = BASE_SYSTEM_INSTRUCTION;

// Helper to identify user from token or context
const getCurrentUserId = (): string => {
    const token = localStorage.getItem('astro_token');
    if (token) {
        return verifyJWT(token) || 'anonymous';
    }
    return 'anonymous';
};

const trackUsageToDb = (prompt: string, response: string, feature: 'chat' | 'horoscope' = 'chat') => {
    // Estimate tokens: 1 token ~= 4 chars (Rough Estimate)
    const inputTokens = Math.ceil(prompt.length / 4);
    const outputTokens = Math.ceil(response.length / 4);

    // Log directly to Supabase via dbService
    const userId = getCurrentUserId();
    logTokenUsage(userId, feature, inputTokens, outputTokens);
};

const getAI = () => {
  if (!ai) {
    if (!process.env.API_KEY) {
      console.warn("API_KEY missing.");
      return null;
    }
    ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  }
  return ai;
};

export const initializeChat = async (customInstruction?: string): Promise<Chat | null> => {
  const client = getAI();
  if (!client) return null;

  if (customInstruction) {
    currentInstruction = customInstruction;
  }

  try {
      chatSession = client.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
          systemInstruction: currentInstruction,
          temperature: 0.7,
          maxOutputTokens: 8192, 
        }
      });
      return chatSession;
  } catch (e) {
      console.warn("Failed to create chat session.", e);
      chatSession = null;
      return null;
  }
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const sendMessageToGemini = async (message: string, isPremium: boolean = false): Promise<string> => {
  if (!chatSession) {
      await initializeChat();
      if (!chatSession) {
          return "I am currently meditating in the cosmic void. Please check your connection or API key configuration.";
      }
  }

  const maxRetries = 2;
  let attempt = 0;

  let apiPrompt = message;
  if (isPremium) {
     apiPrompt = `${message} 

     [PREMIUM REQUEST]: Provide a rich, detailed 'Deep Dive' section. Include specific planetary alignments, Dasha implications, and concrete remedies. Be precise and avoid vague spiritual platitudes. Focus on actionable astrological data.`;
  }

  while (attempt < maxRetries) {
    try {
      if (!chatSession) throw new Error("Session lost");

      const result = await chatSession.sendMessage({
        message: apiPrompt
      });

      const responseText = result.text;
      if (!responseText) throw new Error("Empty response");

      // Log DB Usage
      trackUsageToDb(apiPrompt, responseText, 'chat');

      return responseText;
    } catch (error: any) {
      console.error("Gemini API Error:", error);

      const isQuotaError = error?.status === 429 || error?.code === 429 || error?.message?.includes('quota');
      if (isQuotaError) {
        attempt++;
        if (attempt < maxRetries) {
            await delay(Math.pow(2, attempt) * 1000);
            continue;
        }
      }

      return "The stars are clouded by interference. Please try again in a moment.";
    }
  }
  return "The stars are clouded by interference. Please try again in a moment.";
};

export const generateJsonContent = async (prompt: string, maxTokens: number = 4000, schema?: Schema): Promise<any> => {
    const client = getAI();
    if (!client) return null;

    try {
        const response = await client.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                responseMimeType: 'application/json',
                responseSchema: schema,
                maxOutputTokens: maxTokens
            }
        });

        let text = response.text;
        if (!text) return null;

        trackUsageToDb(prompt, text, 'horoscope');

        if (text.trim().startsWith('```')) {
            text = text.replace(/^```json\s*/, '').replace(/^```\s*/, '').replace(/```$/, '').trim();
        }

        try {
            return JSON.parse(text);
        } catch (parseError) {
            const cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
            try { return JSON.parse(cleanText); } catch (e2) { return null; }
        }
    } catch (e) {
        console.error("JSON Generation Error:", e);
        return null;
    }
};

import React, { useState, useEffect } from 'react';
import { sendAuthOtp, verifyAuthOtp, fetchUserProfile } from '../../services/dbService';

export interface OnboardingData {
  contact: string;
  name: string;
  gender: string;
  date: string;
  time: string;
  place: string;
  password?: string;
  userId?: string; // Newly added
}

interface UserOnboardingProps {
  onSubmit: (data: OnboardingData, tier: 'free' | 'premium' | 'member21') => void;
  onGuruLogin?: () => void;
}

const COUNTRY_CODES = [
    { code: '+91', country: 'IN', label: 'India (+91)' },
    { code: '+1', country: 'US', label: 'USA/Canada (+1)' },
    { code: '+44', country: 'UK', label: 'UK (+44)' },
    { code: '+61', country: 'AU', label: 'Australia (+61)' },
    { code: '+971', country: 'AE', label: 'UAE (+971)' },
    { code: '+65', country: 'SG', label: 'Singapore (+65)' },
    { code: '+49', country: 'DE', label: 'Germany (+49)' },
    { code: '+33', country: 'FR', label: 'France (+33)' },
    { code: '+81', country: 'JP', label: 'Japan (+81)' },
];

const UserOnboarding: React.FC<UserOnboardingProps> = ({ onSubmit, onGuruLogin }) => {
  const [step, setStep] = useState(1);
  const [contactInput, setContactInput] = useState('');
  const [countryCode, setCountryCode] = useState('+91');
  const [otpSent, setOtpSent] = useState(false);
  const [otp, setOtp] = useState('');
  const [isOtpVerified, setIsOtpVerified] = useState(false);
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const [timer, setTimer] = useState(0);
  const [debouncedPlace, setDebouncedPlace] = useState('');
  const [verifiedUserId, setVerifiedUserId] = useState<string | undefined>(undefined);

  const [formData, setFormData] = useState<OnboardingData>({
    contact: '',
    name: '',
    gender: '',
    date: '',
    time: '',
    place: '',
    password: ''
  });

  const isEmailDetected = /[a-zA-Z@]/.test(contactInput);

  useEffect(() => {
    try {
        const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
        let detected = '+91'; 
        if (tz.includes('America')) detected = '+1';
        else if (tz.includes('Europe/London')) detected = '+44';
        else if (tz.includes('Europe')) detected = '+49'; 
        else if (tz.includes('Australia')) detected = '+61';
        else if (tz.includes('Dubai') || tz.includes('Asia/Muscat')) detected = '+971';
        else if (tz.includes('Asia/Singapore')) detected = '+65';
        else if (tz.includes('Asia/Tokyo')) detected = '+81';
        if (COUNTRY_CODES.some(c => c.code === detected)) setCountryCode(detected);
    } catch (e) {}
  }, []);

  useEffect(() => {
    let interval: any;
    if (timer > 0) interval = setInterval(() => setTimer(prev => prev - 1), 1000);
    return () => clearInterval(interval);
  }, [timer]);

  useEffect(() => {
    const handler = setTimeout(() => setDebouncedPlace(formData.place), 1000);
    return () => clearTimeout(handler);
  }, [formData.place]);

  useEffect(() => {
      setErrorMsg(''); 
      const cleanContact = contactInput.trim();
      if (isEmailDetected) {
          setFormData(prev => ({ ...prev, contact: cleanContact }));
      } else {
          setFormData(prev => ({ ...prev, contact: `${countryCode}${cleanContact}` }));
      }
  }, [contactInput, countryCode, isEmailDetected]);

  const handleNext = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setStep(prev => prev + 1);
  };

  const handleSendOtp = async (e: React.FormEvent) => {
      e.preventDefault();
      setIsLoading(true);
      setErrorMsg('');

      const cleanInput = contactInput.trim();
      const contact = isEmailDetected ? cleanInput : `${countryCode}${cleanInput}`;

      try {
        const { profile } = await fetchUserProfile(contact);
        if (profile) {
            setIsLoading(false);
            setErrorMsg("This mobile number or email is already registered. Please login instead.");
            return;
        }
      } catch (err) {}

      const result = await sendAuthOtp(contact);
      setIsLoading(false);

      if (result.success) {
          setOtpSent(true);
          setTimer(60); 
      } else if (result.isRateLimit) {
          alert("Note: You are requesting codes too quickly. Please check your inbox for the previous code.");
          setOtpSent(true);
          setTimer(60);
      } else {
          setErrorMsg(result.message || "Failed to send code.");
      }
  };

  const handleVerifyOtp = async (e: React.FormEvent) => {
      e.preventDefault();
      setIsLoading(true);
      setErrorMsg('');

      const cleanInput = contactInput.trim();
      const contact = isEmailDetected ? cleanInput : `${countryCode}${cleanInput}`;
      const result = await verifyAuthOtp(contact, otp.trim());

      setIsLoading(false);

      if (result.success) {
