export const saveUserProfile = async (user: UserState, password?: string, messages?: Message[]) => {
  if (!supabase || !user.contact) return;
  try {
      // HANDLE EXPIRY: Can be String or Date object. Convert to ISO String.
      let expiryVal = null;
      if (user.subscriptionExpiry) {
          if (typeof user.subscriptionExpiry === 'string') {
              expiryVal = user.subscriptionExpiry;
          } else if (user.subscriptionExpiry instanceof Date) {
              expiryVal = user.subscriptionExpiry.toISOString();
          }
      }

      // Member 21 Safety Check: Ensure expiry is set if tier suggests it
      if (user.tier === 'member21' && !expiryVal) {
          const d = new Date();
          d.setFullYear(d.getFullYear() + 3);
          expiryVal = d.toISOString();
      }

      const payload: any = {
        contact: user.contact,
        name: user.name || '',
        gender: user.gender || null, // Send NULL instead of empty string for optional fields
        birth_date: user.birthDate || null, // DATE type columns choke on empty strings
        birth_time: user.birthTime || null, 
        birth_place: user.birthPlace || null,
        is_premium: !!user.isPremium,
        daily_questions_left: typeof user.dailyQuestionsLeft === 'number' ? user.dailyQuestionsLeft : 0,
        subscription_expiry: expiryVal
        // REMOVED: tier field assignment to prevent DB error
      };

      // If the user is Member 21, ensure we set specific flags that allow us to derive it later
      if (user.tier === 'member21') {
          payload.is_premium = false;
      }

      if (password) payload.password = await hashPassword(password);
      if (messages && messages.length > 0) payload.chat_history = compressAndEncrypt(messages);

      // Prefer ID if available (UUID), otherwise fallback to contact
      if (user.id && user.id.length > 5) {
         // CRITICAL FIX: Use upsert instead of update when ID is present. 
         // This ensures that if the row exists it is updated, but if for any reason (like incomplete registration)
         // the row is missing attributes or needs a forceful write, upsert handles it better.
         // We also include the ID in the payload for the upsert to work on PK.
         const upsertPayload = { ...payload, id: user.id };
         const { error } = await supabase.from('profiles').upsert(upsertPayload, { onConflict: 'id' });
         if (error) console.error("DB: Upsert (by ID) failed", JSON.stringify(error));
      } else {
         const { error } = await supabase.from('profiles').upsert(payload, { onConflict: 'contact' });
         if (error) console.error("DB: Upsert (by Contact) failed", JSON.stringify(error));
      }
  } catch (e) { console.error("DB: Exception saving profile", e); }
};

import React, { useState, useEffect } from 'react';
import { sendAuthOtp, verifyAuthOtp, fetchUserProfile, saveUserProfile } from '../../services/dbService';
import { UserState } from '../../types';

export interface OnboardingData {
  contact: string;
  name: string;
  gender: string;
  date: string;
  time: string;
  place: string;
  password?: string;
  userId?: string; // Newly added
}

interface UserOnboardingProps {
  onSubmit: (data: OnboardingData, tier: 'free' | 'premium' | 'member21') => void;
  onGuruLogin?: () => void;
}

const COUNTRY_CODES = [
    { code: '+91', country: 'IN', label: 'India (+91)' },
    { code: '+1', country: 'US', label: 'USA/Canada (+1)' },
    { code: '+44', country: 'UK', label: 'UK (+44)' },
    { code: '+61', country: 'AU', label: 'Australia (+61)' },
    { code: '+971', country: 'AE', label: 'UAE (+971)' },
    { code: '+65', country: 'SG', label: 'Singapore (+65)' },
    { code: '+49', country: 'DE', label: 'Germany (+49)' },
    { code: '+33', country: 'FR', label: 'France (+33)' },
    { code: '+81', country: 'JP', label: 'Japan (+81)' },
];

const UserOnboarding: React.FC<UserOnboardingProps> = ({ onSubmit, onGuruLogin }) => {
  const [step, setStep] = useState(1);
  const [contactInput, setContactInput] = useState('');
  const [countryCode, setCountryCode] = useState('+91');
  const [otpSent, setOtpSent] = useState(false);
  const [otp, setOtp] = useState('');
  const [isOtpVerified, setIsOtpVerified] = useState(false);
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const [timer, setTimer] = useState(0);
  const [debouncedPlace, setDebouncedPlace] = useState('');
  const [verifiedUserId, setVerifiedUserId] = useState<string | undefined>(undefined);

  const [formData, setFormData] = useState<OnboardingData>({
    contact: '',
    name: '',
    gender: '',
    date: '',
    time: '',
    place: '',
    password: ''
  });

  const isEmailDetected = /[a-zA-Z@]/.test(contactInput);

  useEffect(() => {
    try {
        const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
        let detected = '+91'; 
        if (tz.includes('America')) detected = '+1';
        else if (tz.includes('Europe/London')) detected = '+44';
        else if (tz.includes('Europe')) detected = '+49'; 
        else if (tz.includes('Australia')) detected = '+61';
        else if (tz.includes('Dubai') || tz.includes('Asia/Muscat')) detected = '+971';
        else if (tz.includes('Asia/Singapore')) detected = '+65';
        else if (tz.includes('Asia/Tokyo')) detected = '+81';
        if (COUNTRY_CODES.some(c => c.code === detected)) setCountryCode(detected);
    } catch (e) {}
  }, []);

  useEffect(() => {
    let interval: any;
    if (timer > 0) interval = setInterval(() => setTimer(prev => prev - 1), 1000);
    return () => clearInterval(interval);
  }, [timer]);

  useEffect(() => {
    const handler = setTimeout(() => setDebouncedPlace(formData.place), 1000);
    return () => clearTimeout(handler);
  }, [formData.place]);

  useEffect(() => {
      setErrorMsg(''); 
      const cleanContact = contactInput.trim();
      if (isEmailDetected) {
          setFormData(prev => ({ ...prev, contact: cleanContact }));
      } else {
          setFormData(prev => ({ ...prev, contact: `${countryCode}${cleanContact}` }));
      }
  }, [contactInput, countryCode, isEmailDetected]);

  const handleNext = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();

    // STEP 4 COMPLETION TRIGGER: SAVE FULL PROFILE
    if (step === 4) {
        setIsLoading(true);
        try {
            // Construct the UserState for DB save
            // We use 'verifiedUserId' obtained from OTP step
            const userPayload: UserState = {
                id: verifiedUserId,
                contact: formData.contact,
                name: formData.name,
                gender: formData.gender,
                birthDate: formData.date,
                birthTime: formData.time,
                birthPlace: formData.place,
                dailyQuestionsLeft: 1, // Default free limit
                isPremium: false,
                tier: 'free',
                hasOnboarded: false, // Not fully finished until payment/final step
                language: 'en'
            };

            // Upsert full details. Password was saved earlier or can be updated here if needed.
            await saveUserProfile(userPayload, formData.password);

        } catch (e) {
            console.error("Failed to save profile at Step 4", e);
            // Optionally block progress, but we'll allow proceed to keep flow moving 
            // and rely on final save in App.tsx as backup
        } finally {
            setIsLoading(false);
        }
    }

    setStep(prev => prev + 1);
  };

  const handleSendOtp = async (e: React.FormEvent) => {
      e.preventDefault();
      setIsLoading(true);
      setErrorMsg('');

      const cleanInput = contactInput.trim();
      const contact = isEmailDetected ? cleanInput : `${countryCode}${cleanInput}`;

      try {
        const { profile } = await fetchUserProfile(contact);
        if (profile) {
            setIsLoading(false);
            setErrorMsg("This mobile number or email is already registered. Please login instead.");
            return;
        }
      } catch (err) {}

      const result = await sendAuthOtp(contact);
      setIsLoading(false);

      if (result.success) {
          setOtpSent(true);
          setTimer(60); 
      } else if (result.isRateLimit) {
          alert("Note: You are requesting codes too quickly. Please check your inbox for the previous code.");
          setOtpSent(true);
          setTimer(60);
      } else {
          setErrorMsg(result.message || "Failed to send code.");
      }
  };

  const handleVerifyOtp = async (e: React.FormEvent) => {
      e.preventDefault();
      setIsLoading(true);
      setErrorMsg('');

      const cleanInput = contactInput.trim();
      const contact = isEmailDetected ? cleanInput : `${countryCode}${cleanInput}`;
      const result = await verifyAuthOtp(contact, otp.trim());

      if (result.success) {
          setIsOtpVerified(true);
