                        </div>
                    </div>
                  </>
              ) : (
                  <p className="text-center text-mystic-500 py-10">Unable to fetch insights. Please try again.</p>
              )}
          </div>
      </div>
  );

  const renderFullForecast = (type: 'weekly' | 'monthly') => {
