                <div>
                    <h3 className="text-xl font-serif text-white">Daily Cosmic Rhythm</h3>
                    <p className="text-xs text-mystic-400 mt-1 font-mono uppercase">
                        {horoscopeData?.meta?.dailyDate || new Date().toLocaleDateString()}
