        if (error) {
            logError('fetchProfiles', error);
            return [];
        }
        if (!data || data.length === 0) return [];

        const mappedUsers = data.map((u: any) => {
            let tier = 'free';
            const now = new Date();
            const expiry = u.subscription_expiry ? new Date(u.subscription_expiry) : null;

            if (u.is_premium) {
                tier = 'premium';
