             setHoroscopeData({ 
                 starSign: sign, 
                 meta: { dailyDate: todayIST },
                 daily: { overview: "Stars are shifting.", simple_overview: "Aligning energies.", dos: ["Meditate"], donts: ["Stress"], luckyColor: "White", luckyNumber: "7" }, 
