        const totalTokens = data.reduce((acc, curr) => acc + (curr.total_tokens || 0), 0);
        return { totalRequests: data.length, estimatedTokens: totalTokens };
    } catch (e) { return { totalRequests: 0, estimatedTokens: 0 }; }
};

