          details: t.details,
          relatedEntityId: t.related_entity_id,
          _created_at: t.created_at 
      }));

      return mapped.sort((a: any, b: any) => {
          return new Date(b._created_at || 0).getTime() - new Date(a._created_at || 0).getTime();
      });

  } catch (e) { 
      logError('fetchTransactions:Exception', e);
      return []; 
  }
};

