  try {
      const { data, error } = await supabase.from('transactions').select('*');

      if (error) {
          logError('fetchTransactions', error);
          return [];
      }
      if (!data || data.length === 0) return [];

      const mapped = data.map((t: any) => ({ 
          id: t.id, 
          userId: t.user_id, 
          userName: t.user_name || 'Anonymous', 
          amount: t.amount, 
          type: t.type, 
