              setMessages([{
                  id: generateId(), 
                  text: txt || "Welcome.", 
                  sender: Sender.AI, 
                  timestamp: new Date(), 
                  isLocked: shouldLock, 
                  metadata: shouldLock ? { status: 'locked' } : undefined,
