    console.log("⬆️ [DB Sending] saveCachedReading:", key);
    if (!supabase) return;
    try { 
        const { error } = await supabase.from('natal_cache').upsert({ id: key, response }, { onConflict: 'id' }); 
        if (error) throw error;
        console.log("⬇️ [DB Success] saveCachedReading:", key);
